package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TokenBuffer constructor.
 */
public class TokenBuffer_TokenBuffer_TriageGen1Test {

    @Test
    public void testConstructorWithParserAndContext_NativeIdsTrue() {
        // Arrange
        JsonParser p = mock(JsonParser.class);
        DeserializationContext ctxt = mock(DeserializationContext.class);
        ObjectCodec codec = new ObjectMapper();

        when(p.getCodec()).thenReturn(codec);
        when(p.canReadTypeId()).thenReturn(true);
        when(p.canReadObjectId()).thenReturn(true);

        // Act
        TokenBuffer tb = new TokenBuffer(p, ctxt);

        // Assert
        assertEquals("Codec should be initialized from parser", codec, tb.getCodec());
        assertTrue("Should have native type IDs", tb.canWriteTypeId());
        assertTrue("Should have native object IDs", tb.canWriteObjectId());
        assertNotNull("Write context should be initialized", tb.getOutputContext());
    }

    @Test
    public void testConstructorWithParserAndContext_NativeIdsFalse() {
        // Arrange
        JsonParser p = mock(JsonParser.class);
        DeserializationContext ctxt = mock(DeserializationContext.class);
        ObjectCodec codec = new ObjectMapper();

        when(p.getCodec()).thenReturn(codec);
        when(p.canReadTypeId()).thenReturn(false);
        when(p.canReadObjectId()).thenReturn(false);

        // Act
        TokenBuffer tb = new TokenBuffer(p, ctxt);

        // Assert
        assertEquals(codec, tb.getCodec());
        assertFalse("Should not have native type IDs", tb.canWriteTypeId());
        assertFalse("Should not have native object IDs", tb.canWriteObjectId());
    }

    @Test
    public void testConstructorWithParserAndContext_MixedNativeIds() {
        // Arrange
        JsonParser p = mock(JsonParser.class);
        DeserializationContext ctxt = mock(DeserializationContext.class);
        ObjectCodec codec = new ObjectMapper();

        when(p.getCodec()).thenReturn(codec);
        when(p.canReadTypeId()).thenReturn(true);
        when(p.canReadObjectId()).thenReturn(false);

        // Act
        TokenBuffer tb = new TokenBuffer(p, ctxt);

        // Assert
        assertTrue("Should have native type IDs", tb.canWriteTypeId());
        assertFalse("Should not have native object IDs", tb.canWriteObjectId());
    }

    @Test
    public void testConstructorWithParserAndContext_MixedNativeIdsReverse() {
        // Arrange
        JsonParser p = mock(JsonParser.class);
        DeserializationContext ctxt = mock(DeserializationContext.class);
        ObjectCodec codec = new ObjectMapper();

        when(p.getCodec()).thenReturn(codec);
        when(p.canReadTypeId()).thenReturn(false);
        when(p.canReadObjectId()).thenReturn(true);

        // Act
        TokenBuffer tb = new TokenBuffer(p, ctxt);

        // Assert
        assertFalse("Should not have native type IDs", tb.canWriteTypeId());
        assertTrue("Should have native object IDs", tb.canWriteObjectId());
    }
}
